// One visual identity for the app, the website, the owner desk and the WhatsApp rate cards: the
// master plan's "Shiv UI" colours (warm paper, steel ink, construction amber for actions, navy),
// kept inside the shapes and the Teko headings the app and the website already use. The websites
// read these values as CSS custom properties from app/theme.css, generated by
// scripts/theme-css.mjs from cssVariables() below. The owner desk's own tokens live in
// packages/design/src/tokens.ts; theme.test.ts fails if the two drift apart.

/** The palette. Every key here becomes a CSS custom property (see cssVariables). */
export const palette = {
  /** Page ground: warm paper. */
  ground: '#F6F4EE',
  /** One tone step up from the ground: entries, facts, photo slots. */
  surface: '#FBFAF6',
  /** Cards, slip and sheet paper: the parchi, the rate sheet, the ledger page. */
  paper: '#FFFFFF',
  /** Steel ink: text and the dark rate folder. */
  ink: '#1F2322',
  /** Navy: the folder behind the front one, the owner navigation. */
  ink2: '#243331',
  /** Secondary text. 4.5:1 or better on the ground and on paper. */
  muted: '#5B605D',
  onInk: '#F6F4EE',
  onInkMuted: '#C5CBC8',
  /** Construction amber: actions and the stamp only. Text on it is onAccent. */
  accent: '#E0A42B',
  accentPress: '#C98C14',
  /** Amber used as text, an icon or a line on a light ground (amber itself is only 2:1 there). */
  accentInk: '#7A4E00',
  /** Text on an amber fill. */
  onAccent: '#1F2322',
  ok: '#1F7A4D',
  okSoft: '#E8F4EC',
  warn: '#7A4E00',
  /** Errors and amounts due, always on the soft paper below or on the ground. */
  danger: '#B23A2F',
  dangerSoft: '#F8E6E3',
  /** Text on a saturated solid fill (danger red, brick). */
  onSolid: '#FFFFFF',
  /** Information and the keyboard focus ring. 3:1 or better on every ground. */
  blue: '#2F6DB5',
  /** Lines: tables, forms and the parchi only. */
  rule: '#D9D5C8',
  /** Rate-folder tab tones, front to back. */
  tab1: '#EAE6DA',
  tab2: '#E2DDCF',
  tab3: '#DAD4C4',
  tab4: '#D1CBB9',
  /** Material drawing colours: cement bag, steel bar, brick, sand, stone aggregate. */
  mKraft: '#CDBF9E',
  mSteel: '#5B6670',
  mBrick: '#A9442C',
  mSand: '#C9A35B',
  mStone: '#8E9196',
} as const;

/**
 * Palette plus the names the app used before Direction A. The old names point at the new
 * tokens so screens keep compiling and rendering until each one is restyled.
 */
export const colors = {
  ...palette,
  /** @deprecated Use ink2. */
  inkSoft: palette.ink2,
  /** @deprecated Use rule. */
  line: palette.rule,
  /** @deprecated Use surface. */
  stone: palette.surface,
  /** @deprecated Use mKraft. */
  kraft: palette.mKraft,
  /** @deprecated Use accent. */
  clay: palette.accent,
  /** @deprecated Use accentPress. */
  clayDeep: palette.accentPress,
  /** @deprecated Use onInkMuted. */
  clayOnInk: palette.onInkMuted,
  /** @deprecated Use ok. */
  green: palette.ok,
  /** @deprecated Use okSoft. */
  greenSoft: palette.okSoft,
} as const;

/** 4-point spacing scale. */
export const space = { xs: 4, sm: 8, md: 12, lg: 16, xl: 24, xxl: 32 } as const;

/** One control radius. Paper objects (slips, sheets, the ledger page) stay square-cornered. */
export const radius = {
  control: 4,
  paper: 0,
  /** Status pills only. */
  pill: 999,
  /** @deprecated Every control uses the one radius. */
  sm: 4,
  /** @deprecated Every control uses the one radius. */
  md: 4,
  /** @deprecated Every control uses the one radius. */
  lg: 4,
} as const;

/**
 * Five type sizes for the app, in dp. Nothing goes below 14 so Devanagari stays readable on
 * budget phones in sunlight.
 */
export const textSize = {
  display: 48,
  head: 32,
  lead: 20,
  body: 17,
  small: 14,
  /** @deprecated Use small. */
  caption: 14,
  /** @deprecated Use lead. */
  title: 20,
  /** @deprecated Use head. */
  heading: 32,
} as const;

/** The same five steps for the websites, fluid where the screen allows. */
export const webTextSize = {
  display: 'clamp(3.2rem, 2.2rem + 5vw, 6.5rem)',
  head: 'clamp(2rem, 1.5rem + 2.2vw, 3.2rem)',
  lead: '1.25rem',
  body: '1.0625rem',
  small: '0.875rem',
} as const;

/**
 * Font stacks. Teko 600 sets display, headings and prices in Latin and Devanagari; the phone's
 * own face sets body text; Kalam is the shopkeeper's hand and appears only on the parchi. The
 * websites self-host Teko and Kalam through next/font, which sets --font-teko and --font-kalam.
 */
export const fonts = {
  display:
    "var(--font-teko, 'Teko'), 'Noto Sans Devanagari', 'Kohinoor Devanagari', 'Arial Narrow', sans-serif",
  text: "system-ui, -apple-system, 'Segoe UI', Roboto, 'Noto Sans', 'Noto Sans Devanagari', 'Kohinoor Devanagari', sans-serif",
  hand: "var(--font-kalam, 'Kalam'), 'Noto Sans Devanagari', cursive",
} as const;

/** Smallest comfortable touch target (Android guidance is 48dp). */
export const touch = 48;

/** One easing curve and three durations, matching the website's motion tokens. */
export const motion = {
  quick: 160,
  base: 220,
  enter: 420,
  easing: [0.2, 0.7, 0.2, 1] as const,
};

const kebab = (name: string) =>
  name.replace(/[A-Z]/g, (c) => `-${c.toLowerCase()}`).replace(/(\d+)$/, '-$1');

/** The CSS custom property name for a palette key, e.g. onInkMuted -> --on-ink-muted, tab1 -> --tab-1. */
export const cssVariableName = (key: keyof typeof palette) => `--${kebab(key)}`;

/** The theme as one `:root { ... }` block of CSS custom properties, formatted for Prettier. */
export function cssVariables(): string {
  const [x1, y1, x2, y2] = motion.easing;
  const entries: [string, string][] = [
    ...Object.entries(palette).map(
      ([key, value]) => [cssVariableName(key as keyof typeof palette), value] as [string, string],
    ),
    ...Object.entries(webTextSize).map(([key, value]) => [`--t-${key}`, value] as [string, string]),
    ['--r', `${radius.control}px`],
    ['--touch', `${touch}px`],
    ['--ease', `cubic-bezier(${x1}, ${y1}, ${x2}, ${y2})`],
    ['--quick', `${motion.quick}ms`],
    ['--base', `${motion.base}ms`],
    ['--enter', `${motion.enter}ms`],
    ['--display', fonts.display],
    ['--text', fonts.text],
    ['--hand', fonts.hand],
  ];
  return `:root {\n${entries.map(([name, value]) => `  ${name}: ${value};`).join('\n')}\n}\n`;
}
